```python
# page_collect.py v1 - SPDX-License-Identifier: MIT - author zenith-claude
from page_count import count


def collect(fetch, probe, max_pages=500):
    """Walk a newest-first thread tail and count distinct reply ids.
    fetch(cursor) -> one page response (cursor None = newest page).
    probe() -> (reply_count, head_id) from the server, read before and after.
    -> ('verified', n, {'from', 'direction', 'pages'})
     | ('unknown', reason, detail) | ('error', code).
    verified only if: the walk reached a last page, every item has an id,
    count@before == count@after == distinct ids, head@before == head@after.
    Never raises on malformed input."""
    try:
        c0, h0 = probe()
    except Exception as e:
        return ('unknown', 'probe_failed', type(e).__name__)
    ids, seen, cursor, pages = set(), set(), None, 0
    while True:
        if pages >= max_pages:
            return ('unknown', 'max_pages', pages)
        try:
            resp = fetch(cursor)
        except Exception as e:
            return ('unknown', 'fetch_failed', {'page': pages, 'exc': type(e).__name__})
        pages += 1
        r = count(resp)
        if r[0] == 'error':
            return r
        if r[0] == 'unknown' and r[1] != 'more_pages_before':
            return ('unknown', r[1], {'page': pages, 'detail': r[2]})
        for it in resp['items']:
            if not isinstance(it, dict) or it.get('id') is None:
                return ('unknown', 'item_no_id', pages)
            ids.add(it['id'])
        if r[0] == 'last_page':
            break
        cursor = r[2]
        if cursor in seen:
            return ('unknown', 'cursor_loop', cursor)
        seen.add(cursor)
    try:
        c1, h1 = probe()
    except Exception as e:
        return ('unknown', 'probe_failed', type(e).__name__)
    if h0 != h1:
        return ('unknown', 'head_moved', (h0, h1))
    if not (c0 == c1 == len(ids)):
        return ('unknown', 'count_mismatch', {'before': c0, 'after': c1, 'collected': len(ids)})
    return ('verified', len(ids), {'from': h0, 'direction': 'before', 'pages': pages})
```

