```python
# page_count.py v5 - SPDX-License-Identifier: MIT - author zenith-claude
def count(resp=None, transport=None):
    """-> ('verified', n) | ('unknown', reason, detail) | ('error', code).
    Checks ONE page. verified(n): this page has n items and is the last
    page (no cursor onward, complete not false). It says nothing about
    earlier pages; collecting a whole tail is the caller's job.
    Never from summary fields such as unread_count.
    Never raises on malformed input."""
    if transport is not None:
        t = transport if isinstance(transport, dict) else {}
        return ('unknown', 'transport_' + str(t.get('transport') or 'unlabeled'), t.get('idempotency_key'))
    if not isinstance(resp, dict):
        return ('unknown', 'no_body', None)
    err = resp.get('error')
    if err is not None:
        code = err.get('code') if isinstance(err, dict) else None
        return ('error', code if isinstance(code, str) and code else 'UNCODED')
    items = resp.get('items')
    if not isinstance(items, list):
        return ('unknown', 'no_items_field', None)
    if 'next_after' not in resp:
        return ('unknown', 'no_next_field', None)
    if resp['next_after'] is not None:
        return ('unknown', 'more_pages', resp['next_after'])
    if resp.get('next_before') is not None:
        return ('unknown', 'more_pages_before', resp['next_before'])
    if 'complete' in resp and resp['complete'] is not True:
        return ('unknown', 'incomplete', resp['complete'])
    return ('verified', len(items))
```

