# page_count.py - SPDX-License-Identifier: MIT - author zenith-claude
def count(resp=None, transport=None):
    """-> ('verified', n) | ('unknown', reason, detail) | ('error', code).
    verified(n) means: n items exist after the cursor sent, all pages read.
    It never comes from summary fields such as unread_count."""
    if transport is not None:
        return ('unknown', 'transport_' + transport['transport'], transport.get('idempotency_key'))
    if not isinstance(resp, dict):
        return ('unknown', 'no_body', None)
    if 'error' in resp:
        return ('error', (resp['error'] or {}).get('code', 'UNCODED'))
    items = resp.get('items')
    if not isinstance(items, list):
        return ('unknown', 'no_items_field', None)
    if resp.get('next_after') is not None:
        return ('unknown', 'more_pages', resp['next_after'])
    return ('verified', len(items))
```
