```python
# capsule_lint.py v6 - SPDX-License-Identifier: MIT - author zenith-claude
import json, sys

def freshest(rs, t0, upto=None):
    """Latest recheck in [t0, upto]; tie=True if two at that time disagree."""
    best, tie = None, False
    for r in rs:
        if r['at'] < t0 or (upto is not None and r['at'] > upto):
            continue
        if best is None or r['at'] > best['at']:
            best, tie = r, False
        elif r['at'] == best['at'] and r['result'] != best['result']:
            tie = True
    return best, tie

def _claim(c, by, t0, max_age, out):
    cid = c.get('id')
    for f in ('id', 'kind', 'source'):
        if f not in c:
            out.append((cid, 'missing ' + f))
    if freshest(by.get(cid, []), t0)[0]:
        return
    if c.get('expires_at') is not None and c['expires_at'] <= t0:
        out.append((cid, 'stale: server expiry passed'))
    elif c.get('source') == 'tool' and c['as_of'] < t0 - max_age:
        out.append((cid, 'stale: tool claim older than max_age, show as inherited'))

def _output(o, claims, by, t0, out):
    c = claims.get(o['claim_id'])
    if c is None:
        return out.append((o['claim_id'], 'output for unknown claim'))
    r, tie = freshest(by.get(c['id'], []), t0, o.get('at'))
    if tie:
        return out.append((c['id'], 'recheck tie conflict'))
    exp, at = c.get('expires_at'), o.get('at')
    if exp is not None and at is not None and exp <= at and r is None:
        out.append((c['id'], 'used after server expiry without recheck'))
    if o['written_as'] == 'tool' and r is None:
        out.append((c['id'], 'inherited->tool without recheck before use'))
    if o['value'] == 'unknown':
        if not (r or {}).get('server_field'):
            out.append((c['id'], 'unknown without a server-authored field'))
    elif r is None:
        pass
    elif c.get('kind') == 'action' and r['result'] == 'not_found':
        out.append((c['id'], 'action lookup not_found is unknown, not verified'))
    elif o['value'] != r['result']:
        out.append((c['id'], 'output value differs from freshest recheck before use'))

def lint(capsule, session, max_age=3600):
    """Event-log semantics: an output with 'at' is judged only by rechecks
    in [started_at, output.at]; without 'at' it is a session-end snapshot.
    [] means no linter findings, not permission to act."""
    t0, out, by = session['started_at'], [], {}
    for r in session['rechecks']:
        by.setdefault(r['claim_id'], []).append(r)
    claims = {c.get('id'): c for c in capsule}
    for fn, items, args in ((_claim, capsule, (by, t0, max_age)),
                            (_output, session['outputs'], (claims, by, t0))):
        for x in items:
            try:
                fn(x, *args, out)
            except Exception as e:
                out.append((x.get('id', x.get('claim_id')), 'lint error: ' + type(e).__name__))
    return out

if __name__ == '__main__':
    d = json.load(open(sys.argv[1]))
    for p in lint(d['capsule'], d['session']):
        print(*p, sep=' | ')
```
